"""Seed the built-in prompt templates into PostgreSQL.

The prompt table is the only runtime source.  This migration replaces the old
startup JSON seeder so a fresh database gets the same built-in templates
without keeping a second prompt store in the repository.

Upgrade is additive and idempotent: existing rows, including rows edited in
the system configuration UI, are never overwritten.  Downgrade is a no-op:
the old startup seeder may already have created the same rows, so a reverse
migration cannot safely distinguish rows created by this migration.
"""

from __future__ import annotations

import base64
import gzip
import json
import uuid
from datetime import datetime
from typing import Sequence, Union

from alembic import op
import sqlalchemy as sa


revision: str = "c5d6e7f8a9b0"
down_revision: Union[str, Sequence[str], None] = "b3c4d5e6f7a8"
branch_labels: Union[str, Sequence[str], None] = None
depends_on: Union[str, Sequence[str], None] = None


# Snapshot of the built-in defaults at migration creation. Existing databases
# are managed through the UI or later targeted data migrations.
_DEFAULTS_B64 = """"""


def _defaults() -> list[dict[str, object]]:
    return json.loads(gzip.decompress(base64.b64decode(_DEFAULTS_B64)).decode("utf-8"))


prompt_templates = sa.table(
    "prompt_templates",
    sa.column("id", sa.Uuid()),
    sa.column("name", sa.String()),
    sa.column("name_zh", sa.String()),
    sa.column("category", sa.String()),
    sa.column("type", sa.String()),
    sa.column("system_prompt", sa.Text()),
    sa.column("user_prompt_template", sa.Text()),
    sa.column("is_default", sa.Integer()),
    sa.column("created_at", sa.DateTime()),
    sa.column("updated_at", sa.DateTime()),
)


def _key(row: dict[str, object]) -> tuple[str, str]:
    return str(row["name"]), str(row["category"])


def upgrade() -> None:
    bind = op.get_bind()
    defaults = _defaults()
    existing = {
        (name, category)
        for name, category in bind.execute(
            sa.select(prompt_templates.c.name, prompt_templates.c.category)
        ).fetchall()
    }
    now = datetime.utcnow()
    rows = []
    for default in defaults:
        if _key(default) in existing:
            continue
        rows.append(
            {
                "id": uuid.uuid4(),
                "name": default["name"],
                "name_zh": default.get("name_zh"),
                "category": default["category"],
                "type": default.get("type") or "writing",
                "system_prompt": default.get("system_prompt") or "",
                "user_prompt_template": default.get("user_prompt_template") or "",
                "is_default": int(bool(default.get("is_default", True))),
                "created_at": now,
                "updated_at": now,
            }
        )
    if rows:
        bind.execute(prompt_templates.insert(), rows)


def downgrade() -> None:
    pass
